diff --git a/src/pcre2_substring.c b/src/pcre2_substring.c
index ae43dbbe..14d5ecfb 100644
--- a/src/pcre2_substring.c
+++ b/src/pcre2_substring.c
@@ -223,8 +223,7 @@ pcre2_substring_get_bynumber(pcre2_match_data *match_data, uint32_t stringnumber
     return PCRE2_ERROR_NOMEMORY;
   }
   /* LCOV_EXCL_STOP */
-  yield = PRIV(memctl_malloc)(sizeof(pcre2_memctl) + CU2BYTES(size + 1),
-                              (pcre2_memctl *)match_data);
+  yield = MEMCTL_MALLOC_CSTRING(match_data, sizeof(pcre2_memctl) + CU2BYTES(size));
   if (yield == NULL)
     return PCRE2_ERROR_NOMEMORY;
   yield = (PCRE2_UCHAR *)(((char *)yield) + sizeof(pcre2_memctl));

